// Settled cohort orders have their own reveal. They are never queued Luckboxes
// and must not inherit a Luckbox index, BoxSpin, or a transaction to open them.
import { CHAIN, CONTRACTS } from './chain-config.js';
import { getActingAddress, get, subscribe } from './store.js';
import { readDegenesisOrders, degenesisDay, MAIN_LAUNCH_DAY, DEGENESIS_DAYS } from './degenesis.js';
import { publishPendingActions, clearPendingActions } from './pending-actions.js';
import { registerComponentPoll } from './component-poll.js';
import { displayEth, trimDisplayZeros } from './scaling.js';
import { TX_CONFIRMED_EVENT } from './contracts.js';
import { transactionAffects } from './transaction-effects.js';
import { queueReveal, DEGENESIS_REVEAL_COMPLETE_EVENT, RESULT_REVEAL_ABORT_EVENT } from '../components/reveal-queue.js';

const SOURCE = 'degenesis-results';
const PREFIX = `degenerus:degenesis-results:v1:${CHAIN.id}:${CONTRACTS.GAME?.toLowerCase() ?? 'pending'}`;
export function degenesisResultSequence(order, player) {
  const day = Number(order?.degenesisDay), index = Number(order?.orderIndex);
  if (!order?.resolved || !Number.isInteger(day) || day < 1 || day > 7
    || !Number.isInteger(index) || index < 0 || !/^0x[\da-f]{40}$/i.test(player || '')) return null;
  const address = player.toLowerCase();
  return { kind: 'degenesis', degenesisDay: day,
    presentationId: `${PREFIX}:${address}:${day}:${index}`,
    revealRelease: { address }, result: order.resolved };
}

function pendingDegenesisOrder(order, player) {
  const day = Number(order?.degenesisDay), index = Number(order?.orderIndex);
  if (!Number.isInteger(day) || day < 1 || day > 7 || !Number.isInteger(index) || index < 0
    || !/^0x[\da-f]{40}$/i.test(player || '')) return null;
  return `${PREFIX}:${player.toLowerCase()}:${day}:${index}`;
}

export function mountDegenesisResults({
  readOrders = readDegenesisOrders, enqueue = queueReveal,
  getPlayer = () => get('ui.mode') === 'combined' ? null : getActingAddress(),
  getDay = degenesisDay,
  getClosed = () => get('app.gameState')?.degenesisClosed,
  events = document, storage,
  poll = registerComponentPoll, watch = subscribe,
} = {}) {
  if (storage === undefined) {
    try { storage = globalThis.localStorage; } catch (_) { storage = null; }
  }
  let player = null, rows = [], generation = 0, stopped = false, settled = false, flight = null;
  let observedClosed = getClosed();
  const queued = new Set();
  const consumed = new Set();
  // Only orders observed as pending belong to this queue after launch. A fresh
  // browser must not turn the complete cohort history into new reveal work.
  const pending = new Set();
  const key = address => `${PREFIX}:${address}`;
  const save = () => {
    try { storage?.setItem(key(player), JSON.stringify([...consumed])); } catch (_) { /* private mode */ }
    try { storage?.setItem(`${key(player)}:pending`, JSON.stringify([...pending])); } catch (_) { /* private mode */ }
  };
  const trackPending = () => {
    const day = getDay();
    // The final cohort settles as the main game opens. Unknown startup state
    // is not evidence that historical settled orders are fresh.
    const currentCohorts = Number.isInteger(day) && day >= 1 && day <= MAIN_LAUNCH_DAY;
    let changed = false;
    for (const order of rows) {
      const id = pendingDegenesisOrder(order, player);
      if (!id || consumed.has(id) || pending.has(id) || (order.resolved && !currentCohorts)) continue;
      pending.add(id);
      changed = true;
    }
    if (changed) save();
  };
  const publish = () => publishPendingActions(SOURCE, rows.flatMap(order => {
    const owner = player;
    const id = pendingDegenesisOrder(order, player);
    if (!id || !pending.has(id) || consumed.has(id) || queued.has(id)) return [];
    const seq = degenesisResultSequence(order, player);
    let amount = '';
    try { if (BigInt(order.amountRawWei ?? 0) > 0n) amount = `${trimDisplayZeros(displayEth(BigInt(order.amountRawWei), 4))} ETH\n`; } catch (_) {}
    return [{ id, kind: 'degenesis', state: seq ? 'ready' : 'waiting', pinned: true,
      phase: seq ? 'result-ready' : 'waiting-draw',
      amountLabel: amount.trim(), degenesisDay: Number(order.degenesisDay),
      label: `${amount}DEGENESIS · DAY ${Number(order.degenesisDay)}`,
      detail: seq ? 'Open your settled box' : 'Opens after the daily drawing settles',
      icon: '/app/assets/lootbox/degenesis-box-v2-classic-logo.webp',
      dismissScope: player, order: 30,
      run: seq ? () => {
        if (stopped || player !== owner || String(getPlayer() || '').toLowerCase() !== owner
          || consumed.has(seq.presentationId) || queued.has(seq.presentationId)) return false;
        if (enqueue(seq) === false) return false;
        queued.add(seq.presentationId);
        publish();
        return true;
      } : null,
    }];
  }));
  const refresh = async () => {
    if (stopped) return;
    const address = String(getPlayer() || '').toLowerCase();
    if (address !== player) {
      generation++; flight = null;
      player = address; rows = []; settled = false; consumed.clear(); pending.clear();
      try { for (const id of JSON.parse(storage?.getItem(key(player)) || '[]')) consumed.add(String(id)); }
      catch (_) { /* bad cache */ }
      try { for (const id of JSON.parse(storage?.getItem(`${key(player)}:pending`) || '[]')) pending.add(String(id)); }
      catch (_) { /* bad cache */ }
      publish();
    }
    if (!address) return;
    trackPending();
    publish();
    const closed = getClosed();
    // A regressed chain view must be allowed to discover again. Completion is
    // otherwise permanent: a logical day change cannot reopen the seven cohorts.
    if (closed !== observedClosed && closed != null && Number(closed) < DEGENESIS_DAYS) settled = false;
    observedClosed = closed;
    if (settled) return;
    const context = `${getDay() ?? ''}:${closed ?? ''}`;
    if (flight) {
      if (flight.context !== context) flight.again = true;
      return flight.promise;
    }
    const active = { request: ++generation, context, again: false, promise: null };
    flight = active;
    active.promise = (async () => {
      let response;
      try { response = await readOrders(address, { withStatus: true }); } catch (_) { return; }
      if (stopped || active.request !== generation || address !== String(getPlayer() || '').toLowerCase()) return;
      const orders = Array.isArray(response) ? response : response?.items;
      if (!Array.isArray(orders) || response?.supported === false) return;
      rows = orders;
      trackPending();
      const resolved = new Set(rows.filter(order => order?.resolved != null)
        .map(order => pendingDegenesisOrder(order, address)).filter(Boolean));
      // Only the order snapshot's own degenesisClosed == 7 proves a terminal
      // history. Main launch/day advancement does not wait for mineRun's backlog.
      // Keep this latch in memory: persisted absence would need fresh chain proof
      // after reload, unlike the pending/consumed presentation identities above.
      settled = Number(response?.degenesisClosed) === DEGENESIS_DAYS
        && rows.every(order => order?.resolved != null && pendingDegenesisOrder(order, address))
        && [...pending].every(id => consumed.has(id) || resolved.has(id));
      publish();
    })().finally(() => {
      if (flight !== active) return;
      flight = null;
      if (active.again && !stopped) {
        settled = false;
        return refresh();
      }
    });
    return active.promise;
  };
  const complete = event => {
    const id = String(event.detail?.presentationId || '');
    if (!queued.delete(id)) return;
    const owner = String(event.detail?.address || player || '').toLowerCase();
    if (owner === player && id.startsWith(`${PREFIX}:${player}:`)) {
      consumed.add(id); pending.delete(id); save(); publish();
    } else if (owner && id.startsWith(`${PREFIX}:${owner}:`)) {
      try {
        const prior = new Set(JSON.parse(storage?.getItem(key(owner)) || '[]'));
        prior.add(id); storage?.setItem(key(owner), JSON.stringify([...prior]));
        const remaining = new Set(JSON.parse(storage?.getItem(`${key(owner)}:pending`) || '[]'));
        remaining.delete(id); storage?.setItem(`${key(owner)}:pending`, JSON.stringify([...remaining]));
      } catch (_) { /* private mode */ }
    }
  };
  const abort = event => {
    for (const item of event.detail?.released || []) {
      if (item.kind === 'degenesis') queued.delete(item.presentationId);
    }
    publish();
  };
  events.addEventListener(DEGENESIS_REVEAL_COMPLETE_EVENT, complete);
  events.addEventListener(RESULT_REVEAL_ABORT_EVENT, abort);
  const confirmed = event => {
    if (!transactionAffects(event.detail?.effects, ['degenesis'])) return;
    settled = false;
    if (flight) flight.again = true;
    void refresh();
  };
  events.addEventListener(TX_CONFIRMED_EVENT, confirmed);
  const unsubs = ['connected.address', 'viewing.address', 'ui.mode']
    .map(path => watch(path, () => { void refresh(); }));
  unsubs.push(watch('app.daySync', () => { void refresh(); }));
  let lastDay = getDay(), lastClosed = getClosed();
  unsubs.push(watch('app.gameState', () => {
    const day = getDay(), closed = getClosed();
    if (day !== lastDay || closed !== lastClosed) {
      lastDay = day; lastClosed = closed; void refresh();
    }
  }));
  const unpoll = poll(refresh, 60_000);
  void refresh();
  return { refresh, dispose() {
    stopped = true; generation++;
    unpoll(); unsubs.forEach(fn => fn());
    events.removeEventListener(DEGENESIS_REVEAL_COMPLETE_EVENT, complete);
    events.removeEventListener(RESULT_REVEAL_ABORT_EVENT, abort);
    events.removeEventListener(TX_CONFIRMED_EVENT, confirmed);
    clearPendingActions(SOURCE);
  } };
}
